import{_ as o,o as a,c as r,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Importar Docker Compose","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/compose.md","filePath":"pt-BR/guide/compose.md"}'),i={name:"pt-BR/guide/compose.md"};function t(c,e,d,m,n,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="importar-docker-compose" tabindex="-1">Importar Docker Compose <a class="header-anchor" href="#importar-docker-compose" aria-label="Permalink to &quot;Importar Docker Compose&quot;">​</a></h1><p>O Orbit lê um arquivo Compose de um repositório (<code>compose.yaml</code>, <code>compose.yml</code>, <code>docker-compose.yml</code> ou <code>docker-compose.yaml</code> na raiz, ou um caminho que você informar) ou de um arquivo colado ou enviado, e mostra um plano para revisar antes de criar qualquer coisa.</p><h2 id="creates" tabindex="-1">O que ele cria <a class="header-anchor" href="#creates" aria-label="Permalink to &quot;O que ele cria {#creates}&quot;">​</a></h2><ul><li><strong>Bancos:</strong> imagens de PostgreSQL, MySQL (e MariaDB), MongoDB e Redis (e Valkey) viram bancos gerenciados na versão que o Orbit roda. Eles começam vazios: os dados dos volumes do Compose não são migrados. Faça backup com a configuração antiga e restaure no banco novo se precisar deles.</li><li><strong>Aplicações e workers:</strong> um serviço com porta vira uma aplicação, sem porta um worker. Um <code>build:</code> na raiz do repositório com o seu <code>Dockerfile</code> é compilado pelo Orbit a partir do repositório. O resto precisa de uma imagem de contêiner, que a revisão pede.</li><li><strong>Variáveis:</strong> são copiadas, e nomes que parecem secretos viram segredos. Valores que apontam para um banco viram referências, e URLs que apontam para outro serviço são reescritas para o endereço dele dentro do ambiente.</li></ul><h2 id="not-kept" tabindex="-1">O que ele não mantém <a class="header-anchor" href="#not-kept" aria-label="Permalink to &quot;O que ele não mantém {#not-kept}&quot;">​</a></h2><p>Volumes de aplicações, <code>env_file</code>, redes, <code>privileged</code>, capabilities, devices, secrets e configs do Compose. A revisão lista cada um, e as instâncias são definidas nas Configurações depois.</p><h2 id="after" tabindex="-1">Depois da importação <a class="header-anchor" href="#after" aria-label="Permalink to &quot;Depois da importação {#after}&quot;">​</a></h2><p>Cada serviço é uma aplicação, worker ou banco comum. Nada os prende mais ao arquivo, então mudanças nele depois não são aplicadas.</p>',8)])])}const v=o(i,[["render",t]]);export{u as __pageData,v as default};
